 ('Cyclopes Craftsmen','SRC_HESIOD_THEOGONY','Hesiod, Theogony 139-146: Brontes, Steropes and Arges, the smith-Cyclopes who forged Zeus''s thunderbolt.'),
 ('Satyrs','SRC_STRABO_GEOGRAPHY','Hesiod fr. 10a (Merkelbach-West), transmitted by Strabo 10.3.19: the Satyrs born with the Nymphs and Kouretes.'),
 ('Silenus','SRC_HOMERIC_HYMNS','Homeric Hymn 5 (to Aphrodite) 262: the Sileni who mate with nymphs in the depths of caves.'),
 ('Maenads','SRC_EURIPIDES_BACCHAE','Euripides, Bacchae 55: the thiasos of bacchant women of Dionysus.'),
 ('Thyiads','SRC_PAUSANIAS_DESCRIPTION','Pausanias 10.4.3: the Thyiades, women who dance the biennial Dionysiac rites on Parnassus.'),
 ('Nosoi','SRC_HESIOD_WORKS_DAYS','Hesiod, Works and Days 102-104: the countless Nosoi (Diseases) that escaped Pandora''s jar.'),
 ('Oneiroi','SRC_HESIOD_THEOGONY','Hesiod, Theogony 211-212: Nyx bears the tribe of Dreams (Oneiroi).'),
 ('Morpheus','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses 11.635: Morpheus, shaper of human forms, son of Somnus.'),
 ('Phantasos','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses 11.642: Phantasos, who takes the form of earth, rock, water and wood.'),
 ('Phobetor','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses 11.640: "Icelos to the gods, Phobetor to mortals," who takes beast-forms.'),
 ('Zagreus','SRC_NONNUS_DIONYSIACA','Nonnus, Dionysiaca 6.155-205: the horned infant Zagreus, dismembered by the Titans.'),
 ('Pallas','SRC_HESIOD_THEOGONY','Hesiod, Theogony 376, 383-385: the Titan Pallas, father of Zelos, Nike, Kratos and Bia by Styx.'),
 ('Eurynome Primordial','SRC_APOLLONIUS_ARGONAUTICA','Apollonius, Argonautica 1.503-506: Eurynome and Ophion ruled Olympus before Cronus and Rhea.'),
 ('Hydros','SRC_DAMASCIUS_PRINCIPLES','Damascius, De Principiis 123: Hydros (Water), with Mud, the first principle of the Orphic Rhapsodic theogony.'),
 ('Ophion','SRC_APOLLONIUS_ARGONAUTICA','Apollonius, Argonautica 1.503-506: the primordial serpent Ophion who ruled Olympus with Eurynome.'),
 ('Thesis','SRC_DAMASCIUS_PRINCIPLES','Damascius, De Principiis 123: Thesis (Disposition), an ineffable first principle of the Orphic theogony.'),
 ('Nesoi','SRC_CALLIMACHUS_HYMNS','Callimachus, Hymn 4 (to Delos) 300: the islands form a choir around Delos.'),
 ('Priapus','SRC_PAUSANIAS_DESCRIPTION','Pausanias 9.31.2: Priapos, most revered at Lampsacus, son of Dionysus and Aphrodite.'),
 ('Mên','SRC_STRABO_GEOGRAPHY','Strabo, Geography 12.3.31: the Anatolian lunar god Men Pharnakou, worshipped at Ameria in Pontus.'),
 ('Kourotrophos','SRC_HOMERIC_HYMNS','Homeric Hymn 30 (to Gaia) 1-3: Gaia the all-nurturing mother of all (the Kourotrophos function).'),
 ('Themis at Delphi','SRC_AESCHYLUS_ORESTEIA','Aeschylus, Eumenides 1-8: Themis held the Delphic oracular seat, second after Gaia, before Apollo.'),
 ('Charites','SRC_HESIOD_THEOGONY','Hesiod, Theogony 907-911: the three Graces Aglaia, Euphrosyne and Thalia, borne by Eurynome to Zeus.'),
 ('Muses','SRC_HESIOD_THEOGONY','Hesiod, Theogony 75-79: the nine daughters of Zeus and Mnemosyne.'),
 ('Muses Heliconian','SRC_HESIOD_THEOGONY','Hesiod, Theogony 1-2: the opening invocation of "the Heliconian Muses."'),
 ('Nereids','SRC_HESIOD_THEOGONY','Hesiod, Theogony 240-264: the fifty daughters of Nereus and Doris.'),
 ('Oceanids','SRC_HESIOD_THEOGONY','Hesiod, Theogony 346-366: the three thousand daughters of Oceanus and Tethys.'),
 ('Erinyes','SRC_HESIOD_THEOGONY','Hesiod, Theogony 183-185: born from the blood of the castrated Ouranos.'),
 ('Eumenides','SRC_AESCHYLUS_ORESTEIA','Aeschylus, Eumenides 1021-1047: the Erinyes transformed into the kindly Semnai/Eumenides.'),
 ('Horae','SRC_HESIOD_THEOGONY','Hesiod, Theogony 901-906: Eunomia, Dike and Eirene, daughters of Zeus and Themis.'),
 ('Eileithyia','SRC_HESIOD_THEOGONY','Hesiod, Theogony 922: daughter of Zeus and Hera, goddess of childbirth.'),
 ('Telchines','SRC_DIODORUS_SICULUS','Diodorus Siculus 5.55: the Telchines, first inhabitants of Rhodes, smiths and weather-magicians who reared Poseidon.')
) AS t(name, src, note)
JOIN entities e ON e.tradition LIKE 'Greek%' AND e.canonical_name = t.name
ON CONFLICT DO NOTHING;

-- ── Verify ───────────────────────────────────────────────────────────────────
SELECT round(100.0*count(*) FILTER (WHERE ok)/count(*),1) AS pct_rigorous_overall,
       count(*) FILTER (WHERE NOT ok) AS ref_only_total
FROM (SELECT e.entity_id,
  bool_or(s.source_type IN ('primary text','primary inscription/artifact','heresiological source','secondary scholarship')) ok
  FROM entities e LEFT JOIN entity_sources es ON es.entity_id=e.entity_id LEFT JOIN sources s ON s.source_id=es.source_id
  GROUP BY e.entity_id) g;
SELECT 'Greek ref-only remaining' AS label, count(*) FROM (
  SELECT e.entity_id, bool_or(s.source_type IN ('primary text','primary inscription/artifact','heresiological source','secondary scholarship')) ok
  FROM entities e LEFT JOIN entity_sources es ON es.entity_id=e.entity_id LEFT JOIN sources s ON s.source_id=es.source_id
  WHERE e.tradition LIKE 'Greek%' GROUP BY e.entity_id) g WHERE NOT ok;
SELECT count(*) AS dup_pairs FROM (SELECT entity_id, source_id FROM entity_sources GROUP BY 1,2 HAVING count(*)>1) d;
SELECT count(*) AS unsourced FROM entities e WHERE NOT EXISTS (SELECT 1 FROM entity_sources s WHERE s.entity_id=e.entity_id);
SELECT * FROM v_release_metrics;

COMMIT;
